// Declares the payments module: what it needs, what it shows, what it opens.
module com.bank.payments {
    // Public API package — visible to every module that reads us.
    exports com.bank.payments.api;

    // Qualified export: only the reporting module may use this internal package.
    exports com.bank.payments.internal to com.bank.reporting;

    // Open the model so Jackson/Hibernate can reflect over private fields.
    opens com.bank.payments.model;
    // Note: com.bank.payments.internal is NOT exported to the world — encapsulated.
}
