package com.bank.payments.internal;

import com.bank.payments.model.Account;
import java.math.BigDecimal;

// This class is INTERNAL. Because the package is not exported to the world,
// no outside module can see it. We are free to refactor it any time.
public class TransferValidator {
    public void validate(Account from, BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Transfer amount must be positive");
        }
        if (from.getBalance().compareTo(amount) < 0) {
            throw new IllegalStateException("Insufficient funds in " + from.getAccountId());
        }
    }
}
