// ─── File: payments/com/bank/payments/api/TransferService.java ───
package com.bank.payments.api;

import com.bank.payments.internal.TransferValidator;  // allowed: same module
import com.bank.payments.model.Account;
import java.math.BigDecimal;
import java.util.logging.*;

// Exported public API. The ONLY thing other modules may call.
public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private final TransferValidator validator = new TransferValidator();

    public void transfer(Account from, Account to, BigDecimal amount) {
        validator.validate(from, amount);               // uses internal class inside module
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "Transfer Rs." + amount + " from " + from.getAccountId()
                + " to " + to.getAccountId() + " SUCCESS");
    }
}
